/* @autogenerated */
import { inject, untracked } from '@angular/core';
import { CanActivateFn, Router, RouterStateSnapshot, UrlTree } from '@angular/router';
import { IdentityService } from '@shared/context/identity/identity.service';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { AppStateService } from '@shared/context/state/app-state.service';
import { map, Observable, take } from 'rxjs';
import { grants } from '../permission.service';

export type UnauthorizedReason = '401' | '403';

export const isAuthenticated: CanActivateFn = (_route, state) => {
  return apply(state, (user) => (user.authenticated ? true : '401'));
};

/** Deja pasar si el usuario tiene `perm`; si no ha iniciado sesión redirige con `reason=401`, y si no lo tiene con `reason=403`. */
export function hasPermission(perm: string): CanActivateFn {
  return (_route, state) => apply(state, (user) => (!user.authenticated ? '401' : grants(user, perm) ? true : '403'));
}

function apply(
  state: RouterStateSnapshot,
  check: (user: UserInfo) => true | UnauthorizedReason,
): Observable<boolean | UrlTree> {
  const identityService = inject(IdentityService);
  const appState = inject(AppStateService);
  const router = inject(Router);

  return identityService.bootstrap('main').pipe(
    take(1),
    // Se lee el signal y no user$: user$ repite su último valor hasta que corre su effect,
    // y justo tras el bootstrap ese valor todavía es el usuario anónimo
    map(() => {
      const result = check(untracked(appState.user('main')));
      return result === true
        ? true
        : router.createUrlTree(['/unauthorized'], { queryParams: { returnUrl: state.url, reason: result } });
    }),
  );
}
